# Red Hat blog post on MLPerf Inference v6.0, held against the v5.1 and v6.0 result files. python3 -I check_claims_redhat_v60.py
import json,hashlib,re
FILES=['raw/inf_5.0.json','raw/inf_5.1.json','raw/inf_6.0.json']; RAW={f:open(f,'rb').read() for f in FILES}
V5=json.loads(RAW[FILES[0]]); V51=json.loads(RAW[FILES[1]]); V0=json.loads(RAW[FILES[2]]); s=str; pc=lambda x,y:100*(x/y-1); P=lambda x:x['Performance_Result']
def mk(i,q,calc,st,got,out,note): return dict(id=i,quote=q,calc=calc,stated=st,delivered=got,outcome=out,note=note,label_mismatch=False)
def n(x): return int(x.get('Total Accelerators') or 0)
def rows(m,sc,f,cat='closed'): return sorted([x for x in V0 if x['Model']==m and x['Scenario']==sc and x['Category']==cat and f(x)],key=lambda x:-P(x))
b200=lambda x:'B200' in s(x['Accelerator']) and 'GB200' not in s(x['Accelerator'])
h200=lambda x:'H200' in s(x['Accelerator']); b300=lambda x:'B300' in s(x['Accelerator']) and 'GB300' not in s(x['Accelerator'])
RH=[x for x in V0 if x['Submitter'] in('RedHat','Supermicro_RedHat')]
def g(i,m,sc): r=[x for x in RH if x['ID']==i and x['Model']==m and x['Scenario']==sc]; assert len(r)==1,(i,m,sc); return P(r[0])
RR=[]
mods={x['Model'] for x in RH}; accs={re.search(r'(H200|B200|L40S|MI350X)',s(x['Accelerator'])).group(1) for x in RH}
RR.append(mk('RR1','Our submission includes four AI workloads (Whisper-Large-v3, GPT-OSS-120B, Qwen3-VL-235B-A22B, and Llama-2-70b) on NVIDIA (H200, B200, L40S) and AMD (MI350X) GPUs','v6.0 entries from RedHat and Supermicro_RedHat','four workloads on H200, B200, L40S and MI350X',f'models {sorted(mods)}; accelerators {sorted(accs)}','CONSISTENT' if len(mods)==4 and accs=={'H200','B200','L40S','MI350X'} else 'BELOW','Llama-2-70b appears in the file as llama2-70b-99.'))
t=rows('gpt-oss-120b','Offline',b200); rh=g('6.0-0091','gpt-oss-120b','Offline')
RR.append(mk('RR2','the highest offline throughput on B200 for GPT-OSS-120B','closed v6.0 GPT-OSS-120B Offline entries on B200','highest Offline on B200',f'RedHat {rh:,.1f}; next {t[1]["Submitter"]} {P(t[1]):,.1f}; top is {t[0]["Submitter"]}','CONSISTENT' if t[0]['Submitter']=='RedHat' else 'BELOW',''))
w=rows('whisper','Offline',h200)
RR.append(mk('RR3','the leading H200 result on Whisper','closed v6.0 Whisper Offline entries on H200','leading H200 result',f'RedHat {P(w[0]):,.1f}; next {w[1]["Submitter"]} {P(w[1]):,.1f}','CONSISTENT' if w[0]['Submitter']=='RedHat' else 'BELOW',''))
q8=rows('qwen3-vl-235b-a22b','Server',lambda x:b300(x) and n(x)==8); r8=g('6.0-0094','qwen3-vl-235b-a22b','Server')
qs=rows('qwen3-vl-235b-a22b','Server',b200)
RR.append(mk('RR4','the top B200 submission on Qwen3-VL, which exceeded the top B300 performer by 50% in the Server scenario','closed v6.0 Qwen3-VL Server entries on B200 and on eight B300','top B200, +50% over top B300 Server',f'RedHat {r8:.2f} is top B200 of {len(qs)}; top eight-GPU B300 {q8[0]["Submitter"]} {P(q8[0]):.2f}; {pc(r8,P(q8[0])):+.1f}%','CONSISTENT' if qs[0]['Submitter']=='RedHat' and round(pc(r8,P(q8[0])))==50 else 'BELOW','The top B300 figure is read among the eight-GPU B300 entries. The four-GPU GB300 entries are lower.'))
RR.append(mk('RR5','8x B200 offline: 93,071 tokens per second , 8% higher than the next comparable B200 submission','Red Hat B200 Offline entry against the next B200 Offline entry','93,071 tokens/s, +8%',f'{rh:,.1f} against {P(t[1]):,.1f}, {pc(rh,P(t[1])):+.2f}%','CONSISTENT' if round(rh)==93071 and round(pc(rh,P(t[1])))==8 else 'BELOW',''))
gap=pc(P(w[0]),P(w[1]))
RR.append(mk('RR6','8x H200 offline: 36,396 tokens per second , the leading H200 result, 13% faster than the next closest submission','Red Hat H200 Whisper Offline entry against the next H200 Whisper Offline entry','36,396 tokens/s, +13%',f'{P(w[0]):,.1f} against {P(w[1]):,.1f} ({w[1]["Submitter"]}, {w[1]["Accelerator"]}), {gap:+.2f}%','CONSISTENT' if round(gap)==13 else ('ABOVE' if gap>13 else 'BELOW'),'The gain rounds to 14%. The next entry uses the H200 NVL card.'))
h_q=rows('qwen3-vl-235b-a22b','Offline',h200); h_g=rows('gpt-oss-120b','Offline',h200); m_g=rows('gpt-oss-120b','Offline',lambda x:'MI350' in s(x['Accelerator']),None) if False else [x for x in V0 if x['Model']=='gpt-oss-120b' and x['Scenario']=='Offline' and 'MI350' in s(x['Accelerator'])]; l_w=rows('whisper','Offline',lambda x:'L40S' in s(x['Accelerator']))
ok=len(h_q)==1 and len(h_g)==1 and len(m_g)==1 and len(l_w)==1
RR.append(mk('RR7','the only H200 submission for this model in this round ... the only MI350X submission for this model this round ... the first and only L40S submission for Whisper in MLPerf Inference v6.0','v6.0 closed entries by model and accelerator; MI350X GPT-OSS-120B across both divisions','only H200 for Qwen3-VL and GPT-OSS-120B, only MI350X for GPT-OSS-120B, only L40S for Whisper',f'H200 Qwen3-VL {len(h_q)}, H200 GPT-OSS-120B {len(h_g)}, MI350X GPT-OSS-120B {len(m_g)} (division {m_g[0]["Category"]}), L40S Whisper {len(l_w)}','CONSISTENT' if ok else 'BELOW','The MI350X GPT-OSS-120B entry is in the open division, so there is no closed MI350X entry for that model.'))
a,b_,c,d=g('6.0-0094','qwen3-vl-235b-a22b','Server'),g('6.0-0094','qwen3-vl-235b-a22b','Offline'),g('6.0-0095','qwen3-vl-235b-a22b','Offline'),g('6.0-0095','qwen3-vl-235b-a22b','Server')
RR.append(mk('RR8','8x B200 server: 67.86 samples per second ... 8x B200 offline: 79.04 samples per second ... 8x H200: 18.22 samples per second (offline), 11.05 samples per second (server)','Red Hat Qwen3-VL entries 6.0-0094 and 6.0-0095','67.86, 79.04, 18.22 and 11.05',f'{a:.2f}, {b_:.2f}, {c:.2f}, {d:.2f}','CONSISTENT' if (round(a,2),round(b_,2),round(c,2),round(d,2))==(67.86,79.04,18.22,11.05) else 'BELOW',''))
RR.append(mk('RR9','8x B200 server: 71,588 tokens per second ... 8x H200: 28,680 tokens per second (offline), 24,103 tokens per second (server) ... 8XMI350X: 64,293 tokens per second (offline), 58,373 tokens per second (server)','Red Hat GPT-OSS-120B entries 6.0-0091, 6.0-0092 and 6.0-0112','71,588, 28,680, 24,103, 64,293 and 58,373',', '.join(f'{v:,.1f}' for v in (g('6.0-0091','gpt-oss-120b','Server'),g('6.0-0092','gpt-oss-120b','Offline'),g('6.0-0092','gpt-oss-120b','Server'),g('6.0-0112','gpt-oss-120b','Offline'),g('6.0-0112','gpt-oss-120b','Server'))),'CONSISTENT' if [round(v) for v in (g('6.0-0091','gpt-oss-120b','Server'),g('6.0-0092','gpt-oss-120b','Offline'),g('6.0-0092','gpt-oss-120b','Server'),g('6.0-0112','gpt-oss-120b','Offline'),g('6.0-0112','gpt-oss-120b','Server'))]==[71588,28680,24103,64293,58373] else 'BELOW',''))
RR.append(mk('RR10','2x L40S offline: 3,647 tokens per second','Red Hat Whisper L40S entry 6.0-0090','3,647 tokens/s',f'{g("6.0-0090","whisper","Offline"):,.2f}','CONSISTENT' if round(g('6.0-0090','whisper','Offline'))==3647 else 'BELOW',''))
o,sv=g('6.0-0100','llama2-70b-99','Offline'),g('6.0-0100','llama2-70b-99','Server')
RR.append(mk('RR11','Offline: 80,478 tokens per second ... Server: 76,393 tokens per second','Supermicro_RedHat llama2-70b-99 entry 6.0-0100','80,478 and 76,393',f'{o:,.1f} and {sv:,.1f}','CONSISTENT' if (round(o),round(sv))==(80478,76393) else 'BELOW',''))
RR.append(mk('RR12','Table row for Qwen3-VL-235B-A22B on 8x H200 in the post','Red Hat Qwen3-VL H200 entry 6.0-0095, Offline','18.02 samples/s Offline, 11.05 Server',f'Offline {c:.3f}, Server {d:.2f}','CONSISTENT' if round(c,2)==18.02 else 'BELOW','The text under the table gives 18.22, which matches the file. The table prints 18.02.'))
RR.append(mk('RR13','Table row for llama-2-70b on 8x MI350X with Supermicro in the post','Supermicro_RedHat llama2-70b-99 entry 6.0-0100','91,933.10 Offline, 89,019.65 Server',f'{o:,.1f} Offline, {sv:,.1f} Server; the text under the table gives {round(o):,} and {round(sv):,}','CONSISTENT' if round(o,0)==91933 else 'BELOW','No v6.0 entry has either table figure. The text under the table gives 80,478 and 76,393, which match the file.'))
amd=[x for x in V0 if x['Submitter']=='AMD' and x['Model']=='llama2-70b-99' and x['Category']=='closed' and n(x)==8 and 'MI355' in s(x['Accelerator'])]
ao=[P(x) for x in amd if x['Scenario']=='Offline'][0]; asv=[P(x) for x in amd if x['Scenario']=='Server'][0]
RR.append(mk('RR14','our results align with the expected ~80% performance ratio relative to the liquid-cooled MI355X','Supermicro_RedHat MI350X entry against the AMD eight-GPU MI355X llama2-70b-99 entry 6.0-0002','about 80% of the MI355X',f'Offline {100*o/ao:.1f}% ({o:,.0f} of {ao:,.0f}), Server {100*sv/asv:.1f}% ({sv:,.0f} of {asv:,.0f})','CONSISTENT' if round(100*o/ao/10)*10==80 and round(100*sv/asv/10)*10==80 else 'BELOW','Our rule: about 80% is read to the nearest ten, so 75 to 85%.'))
RR.append(mk('RR15','This was Red Hat\'s first MLPerf submission on AMD hardware.','RedHat and Supermicro_RedHat entries on AMD accelerators in the v5.0, v5.1 and v6.0 files','first submission on AMD',f'AMD entries by RedHat in v5.0: {sum(1 for x in V5 if "RedHat" in x["Submitter"] and "AMD" in s(x["Accelerator"]))}, v5.1: {sum(1 for x in V51 if "RedHat" in x["Submitter"] and "AMD" in s(x["Accelerator"]))}','CANNOT_TELL','None before v6.0 in the files used here. Rounds before v5.0 are not in them.'))
RR.append(mk('RR16','This makes our GPT-OSS-120B submission the first for this model on Kubernetes infrastructure.','GPT-OSS-120B entries in the v6.0 file','first on Kubernetes',f'{len({x["ID"] for x in V0 if x["Model"]=="gpt-oss-120b"})} GPT-OSS-120B entries in v6.0; Kubernetes is not a file field','CANNOT_TELL','The file names the software stack, not the orchestrator.'))
RR.append(mk('RR17','We were able to achieve 20% gain in offline performance, and 24% gain in server performance post the submission date.','post-submission results are not result file entries','20% Offline and 24% Server gain after submission','no post-submission entry in the files','CANNOT_TELL',''))
RR.append(mk('RR18','reduced P99 time-to-first-token (TTFT) from 3.4 seconds to 2.1 seconds (~38% improvement)','arithmetic on the two times in the post','~38% improvement',f'{100*(3.4-2.1)/3.4:.1f}% lower','CONSISTENT',"Not a result file field. Checked from the post's own two numbers."))
def vl(L): return len({x['Submitter'] for x in L if 'vllm' in (s(x.get('Software'))+s(x.get('Platform'))+s(x.get('System'))+s(x.get('Notes'))).lower()})
RR.append(mk('RR19','20 submitters in MLPerf v6.0 used vLLM (up from 5 in v5.1)','submitters whose v5.1 and v6.0 records name vLLM in Software, Platform, System or Notes','20 in v6.0, 5 in v5.1',f'v6.0 {vl(V0)} submitters, v5.1 {vl(V51)} submitters name vLLM','BELOW','Our rule: a record that names vLLM in any of the four text fields. The v5.1 count is above the stated 5 and the v6.0 count is below the stated 20. A submitter that uses vLLM without naming it is not counted.'))
q1=rows('qwen3-vl-235b-a22b','Offline',lambda x:True); q2=rows('qwen3-vl-235b-a22b','Server',lambda x:True)
RR.append(mk('RR20','Top in the leaderboard compared to all results','closed v6.0 Qwen3-VL entries, all accelerators','top Offline and top Server',f'Offline top {q1[0]["Submitter"]} {P(q1[0]):.2f}; Server top {q2[0]["Submitter"]} {P(q2[0]):.2f}','CONSISTENT' if q1[0]['Submitter']=='RedHat' and q2[0]['Submitter']=='RedHat' else 'BELOW',''))
json.dump(dict(source=FILES,sha256=[hashlib.sha256(RAW[f]).hexdigest() for f in FILES],claims=RR),open('claims_redhat_v60.json','w'),indent=1)
for c in RR: print(c['id'],c['outcome'],'|',c['stated'][:48],'|',c['delivered'][:210])
